		double r,i;
		r=a-c;
		i=b-d;
		System.out.println(r+"+("+i+")i");
	}
	
	void product(double a, double b, double c, double d) {
		double r,i;
		r=a*c-(b*d);
		i=a*d+(b*c);
		System.out.println(r+"+("+i+")i");
	}

